<?php require __DIR__ . '/../layouts/header.php'; ?>
<main class="container"><div class="page-heading"><div><h1>Inscripciones</h1><p>Consulta las materias, tutores y horarios seleccionados.</p></div></div>
<?php if ($message): ?><p class="success" role="status"><?= e($message) ?></p><?php endif; ?><?php if ($error): ?><p class="alert" role="alert"><?= e($error) ?></p><?php endif; ?>
<div class="table-wrapper card"><table><thead><tr><th>Materia</th><th>Periodo</th><th>Tutor</th><th>Horario</th><th>Aula</th><th>Estudiante</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach ($inscripciones as $enrollment): ?><tr><td><?= e($enrollment['nombre_materia']) ?><span class="table-profile-description">Grupo <?= e($enrollment['nombre_grupo']) ?></span></td><td><?= e($enrollment['nombre_periodo']) ?><span class="table-profile-description"><?= e($enrollment['fecha_inicio']) ?> a <?= e($enrollment['fecha_fin']) ?></span></td><td><?= e($enrollment['tutor']) ?></td><td><?= e($enrollment['dia_semana'] . ' ' . substr($enrollment['hora_inicio'], 0, 5) . ' - ' . substr($enrollment['hora_fin'], 0, 5)) ?></td><td><?= e($enrollment['nombre_aula'] ?: 'Sin aula') ?></td><td><?= e($enrollment['estudiante']) ?></td><td><span class="status status-<?= e($enrollment['estado']) ?>"><?= e($enrollment['estado']) ?></span></td><td><?php if ($role === 'estudiante' && $enrollment['estado'] === 'inscrita'): ?><form method="post" action="<?= e(app_url('inscripciones/cancel.php')) ?>" onsubmit="return confirm('Cancelar esta inscripcion?');"><input type="hidden" name="id_inscripcion" value="<?= (int) $enrollment['id_inscripcion'] ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Cancelar</button></form><?php else: ?>-<?php endif; ?></td></tr><?php endforeach; ?><?php if (!$inscripciones): ?><tr><td colspan="8">No hay inscripciones para mostrar.</td></tr><?php endif; ?></tbody></table></div>
